/*
 * Lite YouTube embed: show a thumbnail, load the player only on click.
 *
 * The chapter markdown (generated by videos/sync_video_embeds.py) contains
 *
 *   <div class="youtube-lite"><a href="https://www.youtube.com/watch?v=ID">…</a></div>
 *
 * MyST keeps only class/id/style/href when it converts HTML, so the video ID
 * travels in the link. Without JavaScript the card is simply that link. With
 * it, each card gets the thumbnail and a click swaps in the inline player.
 *
 * The theme is a server-rendered React single-page app. Cards are enhanced
 * only once the browser is idle after the load event (changing the DOM while
 * React is still hydrating it is a hydration mismatch, React error #418), and
 * again whenever client-side navigation renders new ones.
 */
(function () {
  "use strict";

  var ID_RX = /[?&]v=([A-Za-z0-9_-]{11})/;

  function videoId(card) {
    var link = card.querySelector("a[href*='youtube.com/watch']");
    var match = link && ID_RX.exec(link.getAttribute("href"));
    return match ? match[1] : null;
  }

  function enhance(card) {
    if (card.getAttribute("data-id")) return;
    var id = videoId(card);
    if (!id) return;
    card.setAttribute("data-id", id);
    var img = document.createElement("img");
    img.src = "https://img.youtube.com/vi/" + id + "/hqdefault.jpg";
    img.loading = "lazy";
    img.alt = "";
    card.insertBefore(img, card.firstChild);
    card.classList.add("yt-ready");
  }

  function enhanceAll() {
    var cards = document.querySelectorAll(".youtube-lite");
    for (var i = 0; i < cards.length; i++) enhance(cards[i]);
  }

  function play(card) {
    var id = card.getAttribute("data-id");
    if (!id || card.classList.contains("yt-activated")) return;
    card.classList.add("yt-activated");
    var iframe = document.createElement("iframe");
    iframe.src = "https://www.youtube.com/embed/" + id + "?autoplay=1&rel=0&modestbranding=1";
    iframe.allow = "autoplay; encrypted-media; picture-in-picture";
    iframe.allowFullscreen = true;
    iframe.title = "YouTube video player";
    card.appendChild(iframe);
  }

  // Capture phase so the theme's own link handling never sees the click.
  document.addEventListener(
    "click",
    function (event) {
      var card = event.target.closest && event.target.closest(".youtube-lite.yt-ready");
      if (!card || card.classList.contains("yt-activated")) return;
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.button !== 0) return;
      event.preventDefault();
      event.stopPropagation();
      play(card);
    },
    true
  );

  var pending = false;
  function schedule() {
    if (pending) return;
    pending = true;
    window.setTimeout(function () {
      pending = false;
      enhanceAll();
    }, 0);
  }

  function start() {
    enhanceAll();
    new MutationObserver(schedule).observe(document.body, { childList: true, subtree: true });
  }
  function whenIdle() {
    if (window.requestIdleCallback) window.requestIdleCallback(start, { timeout: 2000 });
    else window.setTimeout(start, 200);
  }
  if (document.readyState === "complete") whenIdle();
  else window.addEventListener("load", whenIdle);
})();
